import unicodedata


def slugify(s):
    s = s.lower()
    s = unicodedata.normalize('NFD', s)
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')
    # Collapse consecutive hyphens
    result = ''
    for ch in out:
        if ch == '-' and result and result[-1] == '-':
            continue
        result += ch
    return result.strip('-')
